// notes: The token help beside the GitHub token field: the steps in index.html, the screenshots here.
"use strict";

// Screenshots of GitHub's own pages (dark theme, November 2026), with the
// account shown as "your-name". They are WebP data URIs because app updates
// carry only css/ and js/. GitHub reworks its pages now and then; the steps
// written next to each picture are what counts.
const HELP_SHOTS = {
  "repo": ["GitHub's new repository page, with the name my-notes and Private chosen",
    "data:image/webp;base64,"],
  "token-name": ["GitHub's new token page: the token's name, its owner and its expiration",
    "data:image/webp;base64,"],
  "token-repo": ["Repository access set to Only select repositories, with my-notes picked",
    "data:image/webp;base64,"],
  "token-perm": ["Permissions with Contents set to Read and write, above the Generate token button",
    "data:image/webp;base64,"],
};
for (const img of document.querySelectorAll("#token-help img[data-shot]")) {
  const shot = HELP_SHOTS[img.dataset.shot];
  if (shot) { img.alt = t(shot[0]); img.src = shot[1]; }
}
